    ["Enable auto-switching"] = "Activar cambio automático",
    ["Automatically equips a loadout when your stance/form changes (warrior stances, druid forms). Out-of-combat only — if a stance change happens in combat, the swap is deferred until combat ends."] = "Equipa automáticamente un conjunto cuando cambias de actitud/forma (actitudes de guerrero, formas de druida). Solo fuera de combate: si el cambio ocurre en combate, se pospone hasta que termine el combate.",
    ["Auto-equip on form"] = "Equipar automáticamente con la forma",
    ["Equip this loadout automatically when the chosen stance/form is activated."] = "Equipa este conjunto automáticamente cuando se active la actitud/forma elegida.",
    ["Auto-Switch on Dual Spec"] = "Cambio automático por doble especialización",
    ["Enable spec auto-switching"] = "Activar cambio automático por especialización",
    ["Automatically equips a loadout when you switch between Spec 1 and Spec 2 (dual spec). Bind each loadout to a spec below. Requires dual spec to be active."] = "Equipa automáticamente un conjunto cuando cambias entre Especialización 1 y Especialización 2 (doble especialización). Asocia abajo cada conjunto a una especialización. Requiere tener la doble especialización activa.",
