    ["Rare (silver)"] = "Raro (plateado)",
    ["Off (default frame)"] = "Desactivado (marco predeterminado)",
    ["Cooldown Manager"] = "Gestor de reutilización",
    ["A row of icons that shows the cooldowns of spells and trinkets you choose — like the retail cooldown manager."] = "Una fila de iconos que muestra los tiempos de reutilización de los hechizos y abalorios que elijas, como el gestor de reutilización de retail.",
    ["Movable cooldown bars grouped however you like (procs, defensives, offensives ...) — like the retail cooldown manager."] = "Barras de reutilización movibles agrupadas a tu gusto (procs, defensivas, ofensivas...), como el gestor de reutilización de retail.",
    ["|cffaaaaaaMovable cooldown bars grouped however you like — e.g. one for procs/buffs, one for defensive cooldowns, one for offensives. Pick or create a group below, then add spells/trinkets to it.|r"] = "|cffaaaaaaBarras de reutilización movibles agrupadas a tu gusto: por ejemplo, una para procs/beneficios, otra para reutilizaciones defensivas y otra para las ofensivas. Elige o crea un grupo abajo y añádele hechizos/abalorios.|r",
    ["Cooldowns"] = "Reutilizaciones",
    ["Groups"] = "Grupos",
    ["Edit group"] = "Editar grupo",
    ["New group"] = "Nuevo grupo",
