    ["|cff888888Nothing in this group yet.|r"] = "|cff888888Aún no hay nada en este grupo.|r",
    ["Cooldown group '%s' unlocked. Drag spells/items onto it; |cff9b6cffdrag|r to move."] = "Grupo de reutilización “%s” desbloqueado. Arrastra hechizos/objetos sobre él; |cff9b6cffarrastra|r para moverlo.",
    ["Cooldown group '%s' locked."] = "Grupo de reutilización “%s” bloqueado.",
    ["Group type"] = "Tipo de grupo",
    ["Buffs & Procs (only show while active)"] = "Beneficios y procs (mostrar solo mientras estén activos)",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaaLos iconos aparecen solo mientras tienes su beneficio/proc; si no, la barra queda vacía. Añade el BENEFICIO (p. ej. Lanzamiento claro) por nombre o ID.|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaaLos iconos muestran el tiempo de reutilización de cada hechizo/abalorio.|r",
    ["Size & offsets"] = "Tamaño y desplazamientos",
    ["Extra settings"] = "Ajustes adicionales",
    ["Friends List"] = "Lista de amigos",
    ["Class-coloured friend names, class icons, faction accent and optional auto-accept for Battle.net invites."] = "Nombres de amigos con color de clase, iconos de clase, acento de facción y aceptación automática opcional de invitaciones de Battle.net.",
    ["Dialog Popups"] = "Ventanas de diálogo",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "Rediseña los diálogos de confirmación de Blizzard (cuenta atrás de salida, borrar objeto, resucitar, invitación a grupo) para que encajen con el aspecto oscuro.",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaaRediseña los diálogos de confirmación de Blizzard (cuenta atrás de salida, borrar objeto, resucitar, invitación a grupo) para que encajen con el aspecto oscuro.|r",
    ["Accent strip"] = "Franja de acento",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "Dibuja un fino degradado de acento en el borde superior de cada diálogo.",
    ["Addon Skins"] = "Aspectos de AddOns",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "Rediseña las ventanas de los AddOns compatibles de terceros para que encajen con el aspecto oscuro: lista de errores, rastreador de misiones, navegador de botín, perfilador y más.",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaaRediseña las ventanas de los AddOns compatibles con el aspecto oscuro. Los aspectos se aplican al cargarse el AddOn; desactivar uno requiere un /reload (el rastreador de misiones se restaura al instante).|r",
    ["not loaded"] = "no cargado",
    ["Map addon"] = "AddOn de mapa",
    ["Dark window skin"] = "Aspecto oscuro de ventana",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "Rediseña toda la ventana de amigos en oscuro con acentos morados. Desactivarlo requiere un /reload para restaurar el marco de Blizzard.",
    ["Class color names"] = "Nombres con color de clase",
