    ["Never (temporarily off)"] = "Nunca (desactivada temporalmente)",
    ["Countdown text size"] = "Tamaño del texto de cuenta atrás",
    ["Percent of the icon size."] = "Porcentaje del tamaño del icono.",
    ["Countdown text color..."] = "Color del texto de cuenta atrás...",
    ["Warn color under (sec)"] = "Color de aviso por debajo de (s)",
    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "Por debajo de estos segundos, la cuenta atrás cambia al color de aviso; 0 desactiva el color de aviso.",
    ["Warn color..."] = "Color de aviso...",
    ["Glow while ready"] = "Destello mientras esté lista",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "Un destello constante mientras la reutilización esté lista y, en el caso de los hechizos, solo mientras se pueda usar de verdad (maná suficiente, etc.).",
    ["Glow color"] = "Color del destello",
    ["Show keybinds"] = "Mostrar asignaciones de teclas",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "Muestra la tecla a la que está asignado el hechizo/objeto en tus barras de acción. Las macros no se reconocen; las páginas de actitud siguen a la barra principal.",
    ["Keybind color..."] = "Color de la asignación de teclas...",
    ["Keep inactive buffs visible (greyed out)"] = "Mantener visibles los beneficios inactivos (atenuados)",
    ["Icons stay in place when the buff runs out, just desaturated - the bar never jumps around."] = "Los iconos se quedan en su sitio cuando acaba el beneficio, solo desaturados: la barra nunca da saltos.",
    ["Add (name / ID)"] = "Añadir (nombre / ID)",
    ["Tracked"] = "Rastreados",
    ["|cff888888Nothing tracked yet.|r"] = "|cff888888Aún no se rastrea nada.|r",
