    ["|cffffffffCOOLDOWNS|r"] = "|cffffffffREUTILIZACIONES|r",
    ["Cooldowns: x=%.0f, y=%.0f"] = "Reutilizaciones: x=%.0f, y=%.0f",
    ["Cooldown Manager unlocked. Drag spells/items onto the bar to add. |cff9b6cffDrag|r the bar to move."] = "Gestor de reutilización desbloqueado. Arrastra hechizos/objetos a la barra para añadirlos. |cff9b6cffArrastra|r la barra para moverla.",
    ["Cooldown Manager locked."] = "Gestor de reutilización bloqueado.",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "Guarda instantáneas con nombre de tus barras de acción, macros y asignaciones de teclas, y las restaura con un clic.",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaaGuarda toda la configuración de tus barras (todas las ranuras de acción, macros y asignaciones de teclas) como un perfil con nombre y la restaura con un clic: por ejemplo, disposiciones de JcJ y de banda, o para copiar una configuración a un twink (almacenamiento para toda la cuenta).|r",
    ["Load"] = "Cargar",
    ["Save current setup"] = "Guardar la configuración actual",
    ["Please enter a profile name first."] = "Introduce primero un nombre de perfil.",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888Aún no hay perfiles guardados.|r",
    ["Also restore macros"] = "Restaurar también las macros",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "Reescribe las macros guardadas por nombre (las existentes se actualizan y las que faltan se crean).",
    ["Also restore keybindings"] = "Restaurar también las asignaciones de teclas",
