    ["Overwrite with current setup"] = "Sobrescribir con la configuración actual",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "Reemplaza el perfil seleccionado por tus barras/macros/asignaciones actuales.",
    ["Note: profile '%s' was saved on another class (%s)."] = "Nota: el perfil “%s” se guardó en otra clase (%s).",
    ["Flight Timer"] = "Temporizador de vuelo",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800La base de datos de rutas de vuelo no está cargada.|r Reinicia WoW por completo (un /reload no basta tras una actualización) para que funcionen los tiempos de vuelo.",
    ["Show flight time bar"] = "Mostrar la barra de tiempo de vuelo",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "Muestra el destino y el tiempo restante mientras viajas en transporte volador. El primer vuelo de una ruta se aprende y a partir de ahí tienes una cuenta atrás.",
    ["Shows a progress bar with the duration of taxi flights. Unknown routes are learned on the first flight."] = "Muestra una barra de progreso con la duración de los vuelos. Las rutas desconocidas se aprenden en el primer vuelo.",
    ["|cffaaaaaaShows a bar with destination and remaining time while on a taxi. The first flight of a route counts up and is saved; from then on you get a countdown.|r"] = "|cffaaaaaaMuestra una barra con el destino y el tiempo restante mientras vuelas. El primer vuelo de una ruta cuenta hacia arriba y se guarda; a partir de ahí tienes una cuenta atrás.|r",
    ["(learning)"] = "(aprendiendo)",
    ["Flight: %s (%s)"] = "Vuelo: %s (%s)",
    ["Print flight time to chat"] = "Mostrar el tiempo de vuelo en el chat",
    ["After landing, prints the measured flight time."] = "Tras aterrizar, muestra el tiempo de vuelo medido.",
    ["Reset learned times"] = "Restablecer los tiempos aprendidos",
    ["Deletes all saved route durations."] = "Elimina todas las duraciones de ruta guardadas.",
    ["Learned flight times reset."] = "Tiempos de vuelo aprendidos restablecidos.",
    ["|cffaaaaaaLearned routes: %d|r"] = "|cffaaaaaaRutas aprendidas: %d|r",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffffTIEMPO DE VUELO|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "Temporizador de vuelo: x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor del temporizador de vuelo activo. |cff9b6cffArrastra|r o usa las |cff9b6cffflechas|r (MAYÚS = 5px).",
    ["Flight timer mover disabled."] = "Movedor del temporizador de vuelo desactivado.",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "Depuración de vuelo activada — haz un vuelo y la resolución aparecerá en el chat.",
