    ["Icon opacity on cooldown"] = "Opacidad del icono en reutilización",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "Atenúa todo el icono mientras la habilidad está en reutilización (100 = desactivado).",
    ["Show cooldown numbers"] = "Mostrar los números de reutilización",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "Los números de cuenta atrás propios del juego en las reutilizaciones (un ajuste del juego, cambiado en vivo).",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaaSe aplica a todas las barras de acción.|r",
    ["Cooldown swipe opacity"] = "Opacidad del barrido de reutilización",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "Cómo de oscura es la capa de barrido de reutilización (0 = invisible).",
    ["Desaturate icons on cooldown"] = "Desaturar los iconos en reutilización",
