    ["Trinkets"] = "Abalorios",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "Dos ranuras de abalorio en pantalla con tiempo de reutilización, selección desplegable y cola automática.",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaaDos ranuras de abalorio con tiempo de reutilización, selección desplegable y cola automática.|nClic izquierdo = usar, clic derecho = desplegable.|r",
    ["Show frame"] = "Mostrar marco",
